void nam_a2lite_reset(nam_a2lite_t* inst) {
    memset(inst->state, 0, sizeof(*inst->state));
    memset(inst->la0_hbuf, 0, sizeof(inst->la0_hbuf));
    for (int l = 0; l < 23; l++) inst->la0_layers[l].wp = 0;
}

void nam_a2lite_set_weights(nam_a2lite_t* inst, const nam_a2lite_weights_t* weights) {
    inst->weights = weights;
    nam_bind(inst);
}

void nam_a2lite_init(nam_a2lite_t* inst, const nam_a2lite_weights_t* weights, nam_a2lite_state_t* state) {
    inst->weights = weights;
    inst->state = state;
    nam_bind(inst);
    nam_a2lite_reset(inst);
}

void nam_a2lite_process(nam_a2lite_t* inst, const float* const* input, float* const* output, int num_frames) {
    nam_a2lite_state_t* const state = inst->state;
    const nam_a2lite_weights_t* const wt = inst->weights;
    const int nf = num_frames;
    const float* restrict cond = input[0];
    nam_blk_t blk;
    blk.cond = cond;
    blk.nf = nf;

    /* ===== Layer array 0 ===== */
    {
        const float* restrict W = wt->la0_w;
        NAM_OPAQUE(W);
        /* Rechannel 1 -> 3 into layer 0's ring */
        {
            float* restrict rb = state->la0_l0_rb;
            const int cols = (5 + NAM_A2LITE_MAX_BUFFER_SIZE);
            int col = inst->la0_layers[0].wp;
            for (int f = 0; f < nf; f++) {
                const float* s = &cond[f * 1];
                const float v0 = W[0] * s[0];
                const float v1 = W[1] * s[0];
                const float v2 = W[2] * s[0];
                rb[col * 3 + 0] = v0;
                rb[col * 3 + 1] = v1;
                rb[col * 3 + 2] = v2;
                if (col < NAM_A2LITE_MAX_BUFFER_SIZE) {
                    rb[(col + cols) * 3 + 0] = v0;
                    rb[(col + cols) * 3 + 1] = v1;
                    rb[(col + cols) * 3 + 2] = v2;
                }
                if (++col == cols) col = 0;
            }
        }
        memset(inst->la0_hbuf + 45, 0, (size_t)nf * 3 * sizeof(float));
        blk.head = inst->la0_hbuf + 45;
        nam_la0_layer_k6(&inst->la0_layers[0], &blk);
        nam_la0_layer_k6(&inst->la0_layers[1], &blk);
        nam_la0_layer_k6(&inst->la0_layers[2], &blk);
        nam_la0_layer_k6(&inst->la0_layers[3], &blk);
        nam_la0_layer_k6(&inst->la0_layers[4], &blk);
        nam_la0_layer_k6(&inst->la0_layers[5], &blk);
        nam_la0_layer_k6(&inst->la0_layers[6], &blk);
        nam_la0_layer_k6(&inst->la0_layers[7], &blk);
        nam_la0_layer_k6(&inst->la0_layers[8], &blk);
        nam_la0_layer_k6(&inst->la0_layers[9], &blk);
        nam_la0_layer_k6(&inst->la0_layers[10], &blk);
        nam_la0_layer_k6(&inst->la0_layers[11], &blk);
        nam_la0_layer_k6(&inst->la0_layers[12], &blk);
        nam_la0_layer_k6(&inst->la0_layers[13], &blk);
        nam_la0_layer_k15(&inst->la0_layers[14], &blk);
        nam_la0_layer_k15(&inst->la0_layers[15], &blk);
        nam_la0_layer_k6(&inst->la0_layers[16], &blk);
        nam_la0_layer_k6(&inst->la0_layers[17], &blk);
        nam_la0_layer_k6(&inst->la0_layers[18], &blk);
        nam_la0_layer_k6(&inst->la0_layers[19], &blk);
        nam_la0_layer_k6(&inst->la0_layers[20], &blk);
        nam_la0_layer_k6(&inst->la0_layers[21], &blk);
        nam_la0_layer_k6(&inst->la0_layers[22], &blk);
        nam_la0_head(W + 1821, inst->la0_hbuf, inst->la0_hout, nf);
        nam_la0_hshift(inst->la0_hbuf, nf);
    }

    {
        const float hs = wt->head_scale;
        const float* restrict hout = inst->la0_hout;
        for (int f = 0; f < nf; f++)
            output[0][f] = hs * hout[f * 1 + 0];
    }
}

void nam_a2lite_prewarm(nam_a2lite_t* inst) {
    float zero[NAM_A2LITE_MAX_BUFFER_SIZE], out[NAM_A2LITE_MAX_BUFFER_SIZE];
    const float* in_ptrs[1];
    float* out_ptrs[1];
    memset(zero, 0, sizeof(zero));
    for (int c = 0; c < 1; c++) in_ptrs[c] = zero;
    for (int c = 0; c < 1; c++) out_ptrs[c] = out;
    for (int done = 0; done < NAM_A2LITE_PREWARM_SAMPLES;) {
        const int n = NAM_A2LITE_PREWARM_SAMPLES - done < NAM_A2LITE_MAX_BUFFER_SIZE
            ? NAM_A2LITE_PREWARM_SAMPLES - done : NAM_A2LITE_MAX_BUFFER_SIZE;
        nam_a2lite_process(inst, in_ptrs, out_ptrs, n);
        done += n;
    }
}

/* ===== Dynamic weight loader (C++ set_weights_ order) ===== */
/* conv: for out i, for in j, for tap k -> dst[(k * cin + j) * cout + i] */
static void nam_ld_conv(float* dst, const float** src, int cin, int cout, int taps) {
    const float* w = *src;
    for (int i = 0; i < cout; i++)
        for (int j = 0; j < cin; j++)
            for (int k = 0; k < taps; k++)
                dst[(k * cin + j) * cout + i] = *w++;
    *src = w;
}
static void nam_ld_copy(float* dst, const float** src, int n) {
    memcpy(dst, *src, (size_t)n * sizeof(float));
    *src += n;
}

